// Example: exponential backoff function
function retryWithExponentialBackoff(operation, maxRetries, initialDelay) {
  let retries = 0;
  let delay = initialDelay;

  function attempt() {
    try {
      return operation();
    } catch (error) {
      if (retries >= maxRetries) {
        throw error;
      }
      retries++;
      delay *= 2;
      setTimeout(attempt, delay);
    }
  }

  return attempt();
}

