// Similar: a function that monitors service health
function serviceMonitor() {
  let failures = 0;
  const threshold = 3;
  let isOpen = false;

  return {
    recordFailure: () => {
      failures++;
      if (failures >= threshold) {
        isOpen = true;
      }
    },
    canRequest: () => !isOpen
  };
}

